import { BULB_PALETTE, calculateLap } from './bulb/geometry';
import { formatCents } from './format';

/** The bar's colours: the bulb's, but starting at its green (the bar was always green up to the goal). */
const GREEN = BULB_PALETTE.findIndex((c) => c.a === '#00d084');
export const PROGRESS_PALETTE: readonly string[] = [...BULB_PALETTE.slice(GREEN), ...BULB_PALETTE.slice(0, GREEN)].map((c) => c.a);

/** The colour of a lap (cycling, as the bulb does). */
export function lapColor(lap: number): string {
  return PROGRESS_PALETTE[lap % PROGRESS_PALETTE.length];
}

/**
 * The bar and its label from known totals (also used by the listing's tiles, which already have them).
 * Past the goal it works like the bulb: each further goal's worth is a new lap, drawn in the next colour over a track
 * that is full in the previous lap's colour.
 */
export function progressBarHtml(raisedCents: number, goalCents: number): string {
  const { lap, fraction } = calculateLap(Math.max(0, raisedCents), goalCents);
  const pct = Math.round(fraction * 1000) / 10;
  const track = lap > 0 ? ` style="background:${lapColor(lap - 1)}"` : '';
  return (
    `<div class="pb-wrap"><div class="pb-track"${track}><div class="pb-fill" style="width:${pct}%;background:${lapColor(lap)}"></div></div>` +
    `<div class="pb-label">${formatCents(raisedCents)} raised of ${formatCents(goalCents)} goal</div></div>`
  );
}
