// Formatting shared by the campaign pages. Pure functions: unit-tested in format.test.ts.

/** 123456 -> "$1,235" (whole dollars; locale as in production: the visitor's own). */
export function formatCents(cents: number): string {
  return (cents / 100).toLocaleString(undefined, {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  });
}

export interface TimeLeft {
  text: string;
  /** The end date, spelled out, for a tooltip. */
  tooltip: string;
}

function plural(n: number, unit: string): string {
  return `${n} ${unit}${n === 1 ? '' : 's'}`;
}

/** "3 days left", "5 hours left", "1 hour 20 minutes left"; null when there is no (valid) end date, or when it has
 *  passed: a campaign past its deadline shows nothing, as if it never had one (user's decision, 2026-11-19). */
export function formatTimeLeft(targetIso: string | null | undefined, now: number = Date.now()): TimeLeft | null {
  if (!targetIso) return null;
  const target = new Date(targetIso);
  if (isNaN(target.getTime())) return null;

  const tooltip = target.toLocaleString(undefined, { dateStyle: 'long', timeStyle: 'short' });
  const diffMs = target.getTime() - now;
  if (diffMs <= 0) return null;

  const diffMinutes = diffMs / 60000;
  const diffHours = diffMinutes / 60;
  const diffDays = diffHours / 24;

  let text: string;
  if (diffDays >= 1) {
    text = `${plural(Math.floor(diffDays), 'day')} left`;
  } else if (diffHours >= 12) {
    text = `${plural(Math.floor(diffHours), 'hour')} left`;
  } else if (diffHours >= 1) {
    const hrs = Math.floor(diffHours);
    const mins = Math.floor(diffMinutes - hrs * 60);
    text = `${plural(hrs, 'hour')}${mins > 0 ? ' ' + plural(mins, 'minute') : ''} left`;
  } else {
    text = `${plural(Math.max(1, Math.round(diffMinutes)), 'minute')} left`;
  }
  return { text, tooltip };
}

/** What mountCountdown touches of its element (an HTMLElement; a plain object in tests). */
type CountdownElement = { textContent: string | null; title: string; style: { display: string } };

/**
 * Keeps `el` showing the time left. Hides it when there is no end date (an ongoing campaign) or once the end date
 * has passed, including while the page is open. Returns a function that stops the updates.
 */
export function mountCountdown(
  el: CountdownElement | null,
  targetIso: string | null | undefined,
  intervalMs: number,
  now: () => number = Date.now,
): () => void {
  if (!el) return () => {};
  let timer: ReturnType<typeof setInterval> | undefined;
  const stop = () => clearInterval(timer);
  const update = () => {
    const info = formatTimeLeft(targetIso, now());
    if (!info) {
      el.style.display = 'none';
      el.textContent = '';
      el.title = '';
      stop(); // nothing more to count down
      return false;
    }
    el.textContent = info.text;
    el.title = info.tooltip;
    return true;
  };
  if (update() && intervalMs) timer = setInterval(update, intervalMs);
  return stop;
}
